// 只绑定真实开工/当面取消或Advance内精确Action终态；每个永久来源裁剪后仍保实际请求身份。
#include "visit_appointment_meeting_receipts.hpp"
#include "visit_appointment_detail.hpp"
#include "resident/kernel/command_types.hpp"
